def is_square(n):
    if n < 0: return False
    sqrt_n = int(n**0.5)
    return sqrt_n**2 == n

def find_a(y1, y2):
    # Q(x) = x^3 + ax^2 + (y2**2 - y1**2 - a - 1)x + y1**2
    # We want to find a such that Q(x) is a square iff x=0 or x=1
    # We can search a in a range
    for a in range(-100, 100):
        b = y2**2 - y1**2 - a - 1
        c = y1**2
        # Check if Q(x) is a square only for x=0, 1
        # For x in a range, check if it's a square.
        # Since it's an elliptic curve, we should also consider negative x.
        is_valid = True
        for x in range(-100, 100):
            if x == 0 or x == 1:
                continue
            val = x**3 + a*x**2 + b*x + c
            if is_square(val):
                is_valid = False
                break
        if is_valid:
            return a
    return None

